var maximumTop = function(nums, k) {
    const n = nums.length;
    if (n === 1) return (k % 2 === 1) ? -1 : nums[0];
    if (k === 0) return nums[0];
    if (k === 1) return n > 1 ? nums[1] : -1;
    if (k > n) return Math.max(...nums);
    let maxVal = 0;
    for (let i = 0; i < k - 1; i++) {
        maxVal = Math.max(maxVal, nums[i]);
    }
    if (k < n) {
        maxVal = Math.max(maxVal, nums[k]);
    }
    return maxVal;
};
